 const authorLabel=a=>a==='student'?'学生':a==='mentor'?'导师（模拟）':'作者未记录';
 function comments(){markComments();if($('mentor-comments').hidden){commentList.replaceChildren();return}commentList.innerHTML=data.comments.length?data.comments.map(c=>{const author=commentAuthor(c),body=author==='mentor'&&c.text.startsWith('导师（模拟）：')?c.text.slice(7):c.text;return '<article class="mentor-comment" data-id="'+escape(c.id)+'"><blockquote class="mentor-comment-quote">'+commentText(c.quote)+'</blockquote><div class="mentor-comment-author">'+authorLabel(author)+'</div><p>'+commentText(body)+' <button data-comment-action="edit">编辑</button></p>'+(c.orphan?'<small>原位置已删除</small>':'')+(c.replies||[]).map((r,i)=>{const reply=replyInfo(c,i);return '<div class="mentor-reply"><div class="mentor-comment-author">'+authorLabel(reply.author)+'</div><p>'+commentText(reply.text)+' <button data-comment-action="edit-reply" data-reply-index="'+i+'">编辑</button></p></div>'}).join('')+'<div><button data-comment-action="locate">定位</button><button data-comment-action="reply">回复</button><button data-comment-action="mentor">模拟导师评论</button></div><div class="mentor-reply-editor" hidden><textarea aria-label="回复评论"></textarea><button data-comment-action="save-reply">保存回复</button></div></article>'}).join(''):'<p>选中文稿中的一段文字，可以在这里添加评论。</p>';}
 function locateComment(c){const select=()=>{const i=blocks.findIndex(b=>c.start>=b.start&&c.end<=b.end),current=doc.querySelector('[data-index="'+i+'"]'),block=blocks[i];if(i<0||!current||!block){say('原位置已删除，评论仍然保留。');return}current.scrollIntoView({block:'center'});const base=block.start+blockPrefix(current,block),start=c.start-base,end=c.end-base;let position=0,from=null,to=null;function visit(node){if(node.nodeType===Node.ELEMENT_NODE&&(node.dataset?.tex!==undefined||node.tagName==='BR')){const n=node.tagName==='BR'?1:node.dataset.tex.length,index=[...node.parentNode.childNodes].indexOf(node);if(from===null&&start===position)from=[node.parentNode,index];if(to===null&&end===position+n)to=[node.parentNode,index+1];position+=n;return}if(node.nodeType===Node.TEXT_NODE){const next=position+node.length;if(from===null&&start>=position&&start<=next)from=[node,start-position];if(to===null&&end>=position&&end<=next)to=[node,end-position];position=next;return}for(const child of node.childNodes)visit(child)}visit(current);if(!from||!to){say('不能可靠定位原选区；评论仍然保留。');return}const range=document.createRange();try{range.setStart(...from);range.setEnd(...to);const sel=window.getSelection();sel.removeAllRanges();sel.addRange(range);}catch{say('不能可靠定位原选区；评论仍然保留。');}};select();setTimeout(select,40);}
 commentList.addEventListener('click',e=>{const action=e.target.dataset.commentAction,card=e.target.closest('.mentor-comment');if(!action||!card)return;const c=data.comments.find(x=>x.id===card.dataset.id);if(!c)return;if(action==='locate'){if(c.orphan){say('原位置已删除，评论仍然保留。');return}locateComment(c);}
  else if(action==='reply'){card.querySelector('.mentor-reply-editor').hidden=false;card.querySelector('textarea').focus()}
  else if(action==='edit'){const author=commentAuthor(c),value=window.prompt('编辑评论',c.text);if(value!==null&&value.trim()){c.author=author;c.text=value;persist();comments()}}
  else if(action==='edit-reply'){const i=Number(e.target.dataset.replyIndex),reply=replyInfo(c,i),value=window.prompt('编辑回复',reply.text);if(value!==null&&value.trim()){c.replies[i]=value;(c.replyAuthors||(c.replyAuthors=[]))[i]=reply.author;persist();comments()}}
  else if(action==='save-reply'){const value=card.querySelector('textarea').value.trim();if(!value)return;const replies=c.replies||(c.replies=[]),i=replies.length;replies.push(value);(c.replyAuthors||(c.replyAuthors=[]))[i]='student';persist();comments()}
  else if(action==='mentor'){const replies=c.replies||(c.replies=[]),i=replies.length;replies.push('这里可以进一步检查前提和推导。此条是演示文字，未调用 AI。');(c.replyAuthors||(c.replyAuthors=[]))[i]='mentor';persist();comments()}
 });
 $('mentor-comments-toggle').addEventListener('click',()=>{$('mentor-comments').hidden=!$('mentor-comments').hidden;$('mentor-comments-toggle').setAttribute('aria-expanded',String(!$('mentor-comments').hidden));comments()});
 function lineDiff(previous,current){const a=previous.split('\n'),b=current.split('\n');let first=0;while(first<a.length&&first<b.length&&a[first]===b[first])first++;let i=a.length,j=b.length;while(i>first&&j>first&&a[i-1]===b[j-1]){i--;j--}return [...a.slice(0,first).map(x=>'  '+x),...a.slice(first,i).map(x=>'- '+x),...b.slice(first,j).map(x=>'+ '+x),...a.slice(i).map(x=>'  '+x)].join('\n');}
 function history(){const list=$('mentor-history-list');if(!data.versions.length){list.innerHTML='<p>还没有版本快照。</p>';return}const chosen=data.versions.find(v=>v.id===selectedVersion);list.innerHTML=data.versions.slice().reverse().map(v=>'<button type="button" data-version="'+escape(v.id)+'">'+escape(v.label)+' · '+escape(new Date(v.time).toLocaleString('zh-CN'))+'</button>').join('')+(chosen?'<section class="mentor-version-preview"><h3>版本源码</h3><pre>'+escape(chosen.source)+'</pre><h3>与当前文稿的差异</h3><p>− 为该版本内容，+ 为当前内容。</p><pre>'+escape(lineDiff(chosen.source,data.source))+'</pre><button type="button" data-version-restore="'+escape(chosen.id)+'">恢复此版本</button></section>':'');}
 $('mentor-version-save').addEventListener('click',()=>{if(data.hasDocument){version('用户保存');say('已保存本地版本快照；本演示不创建 Git 仓库。')}});
 $('mentor-history-toggle').addEventListener('click',()=>{$('mentor-history-list').hidden=!$('mentor-history-list').hidden;$('mentor-history-toggle').setAttribute('aria-expanded',String(!$('mentor-history-list').hidden))});
 $('mentor-history-list').addEventListener('click',e=>{if(e.target.dataset.version){selectedVersion=e.target.dataset.version;history();}});
 function refreshSessions(){const list=$('mentor-session-list');list.innerHTML=workspace.sessions.map(s=>'<option value="'+escape(s.id)+'"'+(s.id===workspace.active?' selected':'')+'>'+escape(s.title)+'</option>').join('');}
 function switchSession(sessionId){const session=workspace.sessions.find(s=>s.id===sessionId);if(!session)return;workspace.active=session.id;data=session.data;data.rounds||=[];prompt.value=data.draft||'';sourceBox.hidden=true;sourceEditing=false;$('mentor-source-toggle').setAttribute('aria-pressed','false');selection=null;pendingSelection=null;selectedVersion=null;render();refreshSessions();refreshCarry();persist();say('本地演示：仅支持固定示例问题，不连接 AI 或创建 Git 仓库。');}
 $('mentor-session-list').addEventListener('change',e=>switchSession(e.target.value));$('mentor-session-new').addEventListener('click',()=>{const session={id:id(),title:'新会话',data:clean()};workspace.sessions.push(session);switchSession(session.id);prompt.focus()});
 function refreshCarry(){const last=data.rounds.at(-1);if($('mentor-last-mode')){$('mentor-last-mode').disabled=!last;$('mentor-last-mode').value=last?.carry||'none'}const rows=workspace.sessions.flatMap(s=>(s.data.rounds||[]).map((r,i)=>'<div class="carry-row"><div>'+escape(s.title)+' · 第 '+(i+1)+' 轮 · '+escape(r.question)+'</div><select data-session="'+escape(s.id)+'" data-round="'+escape(r.id)+'" aria-label="'+escape(s.title)+'第 '+(i+1)+' 轮携带方式">'+['none','temporary','long'].map(m=>'<option value="'+m+'"'+(r.carry===m?' selected':'')+'>'+({none:'不选',temporary:'临时',long:'长期'})[m]+'</option>').join('')+'</select></div>'));$('mentor-carry-list').innerHTML=rows.length?rows.join(''):'<p>还没有可选择的轮次。</p>';}
 $('mentor-carry-open').addEventListener('click',()=>{refreshCarry();$('mentor-carry-dialog').showModal()});$('mentor-carry-close').addEventListener('click',()=>$('mentor-carry-dialog').close());
 $('mentor-carry-list').addEventListener('change',e=>{const s=workspace.sessions.find(x=>x.id===e.target.dataset.session),r=s?.data.rounds.find(x=>x.id===e.target.dataset.round);if(!r)return;r.carry=e.target.value;persist();refreshCarry()});
 if($('mentor-last-mode'))$('mentor-last-mode').addEventListener('change',e=>{const r=data.rounds.at(-1);if(!r)return;r.carry=e.target.value;persist();refreshCarry()});
 $('mentor-example').addEventListener('click',()=>{prompt.value=demoQuestion;data.draft=demoQuestion;persist();prompt.focus()});
 prompt.value=data.draft||'';prompt.addEventListener('input',()=>{data.draft=prompt.value;persist()});
 function send(){const q=prompt.value.trim();if(!q){say('请先输入问题。');return}if(!data.hasDocument){if(q!==demoQuestion){say('此原型仅支持固定示例问题；请点击「填入示例问题」。你的输入仍在编辑框中。');return}const selected=selectedSnapshots();data.question=q;data.source=initialSource;data.initialAI=initialSource;data.authorship=[{start:0,end:initialSource.length,author:'ai'}];data.hasDocument=true;data.draft='';prompt.value='';clearTemporary();data.rounds.push({id:id(),question:q,carry:'temporary',snapshot:selected});activeSession().title=q;version('导师初稿（模拟）');persist();render();refreshSessions();refreshCarry();say('已生成固定示例初稿；未调用 AI。试试输入「请补充归纳法证明」。');return}
  if(!/归纳|检查前提/.test(q)){say('未连接 AI。本地仅支持示例续问「请补充归纳法证明」或「检查前提」；输入仍保留。');return}
  const selected=selectedSnapshots();
  if(/检查前提/.test(q)){const old='这个推导用到了 $n$ 是正整数。',index=data.source.indexOf(old);if(index<0){say('示例批改未找到原句；保留你的修改，没有覆盖。');return}version('导师批改前');editHistory.delete(workspace.active);const replacement='这个配对推导依赖 $n$ 是正整数。对 $n=0$，按空和约定结论也成立。';replaceSource(index,index+old.length,replacement,'ai');data.comments.push({id:id(),start:index,end:index+replacement.length,quote:replacement,author:'mentor',text:'导师（模拟）：补充说明正整数条件和空和边界；未调用 AI。',replies:[],replyAuthors:[],orphan:false,roundId:null});}
  else{version('导师补充前');editHistory.delete(workspace.active);const addition=String.raw`\n\n\section{数学归纳法（模拟补充）}\n\n当 $n=1$ 时等式成立。假设 $1+\cdots+k=\frac{k(k+1)}2$，两边加上 $k+1$，得到 $1+\cdots+(k+1)=\frac{(k+1)(k+2)}2$，所以结论对正整数成立。`.replace(/\\n/g,'\n');replaceSource(data.source.length,data.source.length,addition,'ai');}
  clearTemporary();const next={id:id(),question:q,carry:'temporary',snapshot:selected};data.rounds.push(next);const unassigned=data.comments.filter(c=>c.roundId===null);unassigned.forEach(c=>c.roundId=next.id);data.draft='';prompt.value='';version('导师补充（模拟）');persist();render();refreshCarry();say('已执行固定示例的模拟导师批改；未调用 AI。');}
 function selectedSnapshots(){return workspace.sessions.flatMap(s=>(s.data.rounds||[]).filter(r=>r.carry!=='none').map(r=>({sessionId:s.id,sessionTitle:s.title,id:r.id,question:r.question,comments:JSON.parse(JSON.stringify(s.data.comments.filter(c=>c.roundId===r.id)))})))}
 function clearTemporary(){for(const session of workspace.sessions)for(const round of session.data.rounds||[])if(round.carry==='temporary')round.carry='none';}
 $('mentor-send').addEventListener('click',send);prompt.addEventListener('keydown',e=>{if(e.ctrlKey&&e.key==='Enter'&&!e.isComposing){e.preventDefault();send()}});
 const searchDialog=$('mentor-search-dialog'),searchInput=$('mentor-search-input'),searchResults=$('mentor-search-results'),searchEnhanced=$('mentor-search-enhanced');let enhanced=false;
 function runSearch(){const q=searchInput.value.trim().toLocaleLowerCase(),items=q?blocks.filter(b=>{const s=b.source.toLocaleLowerCase();if(s.includes(q))return true;if(!enhanced)return false;let j=0;for(const ch of s)if(ch===q[j]&&++j===q.length)return true;return false}):[];searchResults.innerHTML=q?(items.map((b,i)=>'<button type="button" data-search-start="'+b.start+'">'+escape(b.source.length>140?b.source.slice(0,140)+'…':b.source)+'</button>').join('')||'<p>没有找到匹配内容。</p>'):'<p>输入文字以搜索当前文稿。</p>';}
 function openSearch(){runSearch();searchDialog.showModal();searchInput.focus()}
 $('mentor-search-open').addEventListener('click',openSearch);$('mentor-search-close').addEventListener('click',()=>searchDialog.close());searchInput.addEventListener('input',runSearch);searchEnhanced.addEventListener('click',()=>{enhanced=!enhanced;searchEnhanced.setAttribute('aria-pressed',String(enhanced));searchEnhanced.textContent='增强搜索：'+(enhanced?'开':'关');runSearch()});searchResults.addEventListener('click',e=>{const start=Number(e.target.dataset.searchStart);if(!Number.isFinite(start))return;searchDialog.close();if(!sourceBox.hidden){sourceBox.hidden=true;sourceEditing=false;$('mentor-source-toggle').setAttribute('aria-pressed','false');render()}const index=blocks.findIndex(b=>b.start===start);doc.querySelector('[data-index="'+index+'"]')?.scrollIntoView({block:'center'});});document.addEventListener('keydown',e=>{if(e.ctrlKey&&!e.shiftKey&&!e.altKey&&e.key.toLowerCase()==='g'){e.preventDefault();if(!searchDialog.open)openSearch()}});
 window.MentorTest={setDocument(source){data=clean();activeSession().data=data;data.source=String(source);data.hasDocument=true;data.authorship=[{start:0,end:data.source.length,author:'ai'}];render();},render,state:()=>JSON.parse(JSON.stringify(data)),workspace:()=>JSON.parse(JSON.stringify(workspace))};
 render();refreshSessions();refreshCarry();say('本地演示：仅支持固定示例问题，不连接 AI 或创建 Git 仓库。');
